CREATE TABLE IF NOT EXISTS integrations (id uuid PRIMARY KEY, type text NOT NULL, name text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_snapshots (integration_id uuid PRIMARY KEY REFERENCES integrations(id), state text NOT NULL, reachable boolean NOT NULL, internet_connected boolean, latency_ms real, packet_loss_percent real, downlink_throughput_bps real, uplink_throughput_bps real, obstruction_fraction real, uptime_seconds bigint, power_watts real, hardware_version text, firmware_version text, last_successful_sample_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS telemetry_samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), integration_id uuid NOT NULL REFERENCES integrations(id), recorded_at timestamptz NOT NULL, metric text NOT NULL, value real NOT NULL, unit text NOT NULL, CONSTRAINT telemetry_dedupe UNIQUE(integration_id, metric, recorded_at));
CREATE INDEX IF NOT EXISTS telemetry_query_idx ON telemetry_samples(integration_id, metric, recorded_at);
CREATE TABLE IF NOT EXISTS network_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), integration_id uuid NOT NULL REFERENCES integrations(id), occurred_at timestamptz NOT NULL, category text NOT NULL, severity text NOT NULL, description text NOT NULL, resolved_at timestamptz, fingerprint text NOT NULL);
CREATE INDEX IF NOT EXISTS events_query_idx ON network_events(integration_id, occurred_at);
CREATE UNIQUE INDEX IF NOT EXISTS events_dedupe_idx ON network_events(integration_id, fingerprint, occurred_at);
